def calculate_route_efficiency(route_data):
    # Assumes route_data is a dictionary { 'Route': {'Distance': X, 'Time': Y}, ... }
    efficiency = {}
    for route, data in route_data.items():
        # Convert time to minutes
        time_in_minutes = data['Time']
        if 'hours' in data['Time'].lower():
            time_in_minutes = data['Time'].replace('hours', '').strip() * 60
        elif 'minutes' in data['Time'].lower():
            time_in_minutes = data['Time'].replace('minutes', '').strip()
        else:
            raise ValueError('Invalid time unit')

        efficiency[route] = data['Distance'] / time_in_minutes  # Lower is better
    return efficiency


