    return returns


def assess_portfolio_risk(portfolio_data):
    # Assumes portfolio_data is a dictionary { "Portfolio": [annual returns], ... }
    # Returns a dictionary with the standard deviation for each portfolio
    # as the value
    risk = {}
    for portfolio, annual_returns in portfolio_data.items():
        risk[portfolio] = np.std(annual_returns)
    return risk


def recommend_risk_management(portfolio_data, risk_threshold):
    # Assumes portfolio_data is a dictionary { "Portfolio": [annual returns], ... }
    # risk_threshold is the maximum standard deviation allowed for a portfolio
    recommendations = {}
    for portfolio, annual_returns in portfolio_data.items():
        if np.std(annual_returns) <= risk_threshold:
            recommendations[portfolio] = "Continue investing"
        else:
            recommendations[portfolio] = "Diversify portfolio"
    return recommendations


